	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	// Compute composite scores from all scorers
	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			// Clamp to [0,1] per INV-1
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	// Find minimum load for spike detection
	minLoad := snapshots[0].EffectiveLoad()
	for _, snap := range snapshots {
		load := snap.EffectiveLoad()
		if load < minLoad {
			minLoad = load
		}
	}

	// Minimal post-scoring: preserve prefix affinity while handling load spikes
	for _, snap := range snapshots {
		load := snap.EffectiveLoad()

		// Progressive load penalty: only kicks in when significantly above minimum
		// This prevents p95 spikes during bursts without breaking cache affinity
		delta := load - minLoad
		if delta >= 3 {
			penalty := 1.0 - 0.05*float64(delta)
			if penalty < 0.75 {
				penalty = 0.75
			}
			scores[snap.ID] *= penalty
		}

		// Guard against extreme memory pressure only
		if snap.KVUtilization > 0.90 {
			scores[snap.ID] *= 0.8
		}
	}

	// Argmax: select instance with highest composite score.
	// Ties broken by first occurrence in snapshot order (strict >).
	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
	// EVOLVE-BLOCK-END

	// Notify observers of routing decision (stateful scorers update their state)
	for _, obs := range ws.observers {
		obs(req, snapshots[bestIdx].ID)
	}

